from lib import *
chapter(6,'science','temperature-and-its-measurement','Temperature and its Measurement',
 ('Hot tea, cold juice','Meena touches the tea and says it is hot, then the juice and says it is cold. But touch can fool us. A cold hand can make warm water feel hot. We need a better way: the thermometer.'),
 [('Hot or cold?',['Our sense of touch is not reliable for judging hot and cold. Put one hand in cold water and the other in warm water, then both in lukewarm water, and the two hands feel different.','To measure how hot or cold something is, we use temperature.']),
  ('Temperature',['Temperature tells us how hot or cold an object is. It is not the same as heat, which is a form of energy.','Temperature is measured in degrees Celsius.']),
  ('Thermometers',['A clinical thermometer measures body temperature. It reads from 35 to 42 degrees Celsius and has a kink that stops the mercury from falling back.','A laboratory thermometer measures from -10 to 110 degrees Celsius and is used for water and other things.','Normal human body temperature is about 37 degrees Celsius.']),
  ('Using a thermometer',['Wash it before and after, shake the mercury down below the normal reading for a clinical thermometer, then place it under the tongue or arm.','For a laboratory thermometer, keep the bulb in the liquid and not touching the sides. Read at eye level.','Never hold a clinical thermometer in hot water.'])],
 [('Normal body temperature is 37 degrees. A child has 39. By how much is it high?',[('Subtract 37 from 39.','Difference.'),('2 degrees above normal.','Fever.')])],
 ('Why can you not trust your hand to measure temperature?',['The hand feels relative to its own state.','A thermometer gives a number everyone can agree on.'],['Mixing up heat and temperature.','Reading from an angle.']),
 ['Touch is unreliable; use a thermometer.','Temperature is measured in degrees Celsius.','A clinical thermometer reads 35 to 42.','Keep the bulb in the liquid and read at eye level.'],
 [mcq('h7-1',1,'Temperature is measured in','degrees Celsius',[('metres','Metres measure length.'),('kilograms','Kilograms measure mass.')],'The thermometer is marked in degrees Celsius.'),
  num('h7-2',1,'Normal body temperature in degrees Celsius is about',37,'Humans keep about 37.',[(98,'98 is in Fahrenheit.')]),
  tf('h7-3',1,'Touch is a reliable way to measure temperature.',False,'It depends on the state of your hand.'),
  mcq('h7-4',1,'A clinical thermometer is used to measure','body temperature',[('room temperature only','It is for the body.'),('boiling water','Its range is too small.')],'It ranges from 35 to 42.'),
  mcq('h7-5',2,'Before using a clinical thermometer you should','shake the mercury down',[('heat it','This can break it.'),('put it in ice','Not needed.')],'Start from a low reading.'),
  tf('h7-6',2,'A clinical thermometer may be placed in boiling water.',False,'Its range is 35 to 42, so it would break.'),
  mcq('h7-7',2,'When reading a laboratory thermometer, keep your eye','level with the mercury',[('above it','This gives a wrong reading.'),('below it','This also gives an error.')],'Avoid parallax.'),
  mcq('h7-8',2,'The laboratory thermometer range is','-10 to 110 degrees Celsius',[('35 to 42','That is the clinical thermometer.'),('0 to 10','Too small.')],'It can measure boiling water.'),
  num('h7-9',3,'Body temperature 39 degrees. How much above normal 37?',2,'39 minus 37.',[(76,'Do not add.')]),
  mcq('h7-10',3,'The bulb of the thermometer should','be in the liquid, not touching the sides',[('touch the bottom','The bottom may be hotter or colder.'),('be out of the liquid','It would read the air.')],'To read the liquid temperature.')],
 keep=['temperature','thermometer'])
chapter(6,'science','a-journey-through-states-of-water','A Journey through States of Water',
 ('Vanishing puddle','After the rain, a puddle in the playground is gone by afternoon. Where did the water go? Water has a travelling story.'),
 [('Water\'s disappearing act',['Water from puddles, wet clothes and ponds goes into the air as an invisible gas called water vapour. This change is evaporation.','The reverse also happens: water vapour cooling to form drops is condensation.']),
  ('States of water',['Water exists in three states: solid ice, liquid water and gaseous water vapour.','Ice melts into water when heated. This is melting. Water freezes into ice when cooled. This is freezing.','Water changes to vapour on heating and the vapour changes to water on cooling.','Boiling is when water changes to vapour throughout, at 100 degrees Celsius.']),
  ('Evaporation faster or slower',['Evaporation is faster when it is hot, when there is wind, when the surface is wide and when the air is dry.','That is why clothes dry faster in the sun and on a windy day.']),
  ('Cooling effect',['Evaporation takes heat from the surroundings, so it cools. Sweat evaporating cools our skin, and water in a clay pot cools because of evaporation from the pot\'s surface.']),
  ('Clouds and rain',['The Sun heats seas and lakes. Water evaporates, rises and cools to form tiny drops that make clouds.','When the drops grow heavy, they fall as rain. This is part of the water cycle.'])],
 [('Why do wet clothes dry faster in summer than in winter?',[('Summer is hotter.','Heat speeds up evaporation.'),('So water leaves the cloth faster.','Evaporation is faster when warm.')])],
 ('Explain how rain is formed.',['Evaporation, cooling and condensation, then falling.'],['Thinking clouds are water vapour only.','Confusing boiling and evaporation.']),
 ['Water has three states: solid, liquid, gas.','Evaporation turns water to vapour; condensation turns vapour to water.','Heat, wind, wide surface and dry air speed evaporation.','Evaporation cools.','The water cycle gives rain.'],
 [mcq('w8-1',1,'Water vapour is water in the','gas state',[('solid state','Solid water is ice.'),('liquid state','Liquid is water you can pour.')],'It is invisible.'),
  mcq('w8-2',1,'Ice changing to water is','melting',[('freezing','That is water to ice.'),('boiling','That is liquid to vapour at 100 degrees.')],'It happens on heating.'),
  tf('w8-3',1,'Condensation is vapour turning to liquid.',True,'On cooling.'),
  mcq('w8-4',1,'Clothes dry faster','on a windy day',[('on a cold, still day','Evaporation is slow.'),('in a wet room','Moist air slows drying.')],'Wind carries the vapour away.'),
  mcq('w8-5',2,'Evaporation causes','cooling',[('heating','It takes heat away.'),('freezing','Not necessarily.')],'It removes heat from the surface.'),
  num('w8-6',2,'Water boils at how many degrees Celsius?',100,'At normal pressure.',[(0,'0 is the freezing point.')]),
  mcq('w8-7',2,'Clouds form when','water vapour cools into tiny drops',[('ice melts','Not the main reason.'),('wind stops','Wind is separate.')],'It is condensation.'),
  mcq('w8-8',2,'Which does not speed evaporation?','A damp, cool, still room',[('Sunlight','Heat speeds it.'),('A wide plate','More surface speeds it.')],'It is the slowest condition.'),
  mcq('w8-9',3,'Sweating cools us because','sweat evaporates taking heat',[('sweat is cold','Sweat is the body\'s temperature.'),('sweat freezes','It does not freeze.')],'Evaporation cools.'),
  mcq('w8-10',3,'Water freezes at','0 degrees Celsius',[('100 degrees Celsius','That is boiling point.'),('37 degrees Celsius','That is body temperature.')],'Freezing point.')],
 keep=['evaporation','condensation','water cycle'])
chapter(6,'science','methods-of-separation-in-everyday-life','Methods of Separation in Everyday Life',
 ('Rice and stones','Grandmother picks tiny stones out of rice before cooking. This is separation. We separate mixtures every day: tea leaves from tea, cream from milk, salt from seawater.'),
 [('Mixtures',['A mixture has two or more substances that are not chemically joined and can be separated.','We separate to remove harmful or unwanted parts, to get useful parts or to get pure substances.']),
  ('Methods for solid mixtures',['Handpicking removes large unwanted pieces, such as stones from rice.','Winnowing separates heavier grain from lighter husk using wind.','Sieving separates smaller pieces from larger ones using holes of a suitable size, like flour from bran.','Magnetic separation removes iron from a mixture using a magnet.']),
  ('Solids from liquids',['Sedimentation lets heavier particles settle at the bottom. Decantation pours off the clear liquid on top.','Filtration passes the mixture through filter paper or a cloth. The solid stays and the liquid goes through.','Evaporation of water from salt water leaves the salt behind. This is how salt is made from seawater.']),
  ('Other methods',['Churning separates butter from curd by spinning. Dissolving and filtering can separate sand and salt: dissolve salt in water, filter out sand and evaporate the water.','We often use more than one method together.'])],
 [('How can you get salt from a mixture of salt and sand?',[('Add water to dissolve the salt.','Sand does not dissolve.'),('Filter to remove sand, then evaporate the water to get salt.','Use two methods.')])],
 ('Explain how a farmer separates wheat grains from husk.',['Winnowing.','Wind carries away the lighter husk.'],['Using filtration for dry solids.','Forgetting that sand does not dissolve.']),
 ['A mixture can be separated by physical methods.','Handpicking, winnowing, sieving and magnets work on solids.','Sedimentation, decantation and filtration work for solids in liquids.','Evaporation recovers a dissolved solid.'],
 [mcq('s9-a1',1,'Winnowing separates','grain from husk using wind',[('salt from water','This is evaporation.'),('iron from sand','This uses a magnet.')],'Light husk blows away.'),
  mcq('s9-a2',1,'Filtration removes','solid particles from a liquid',[('salt in water','Salt passes through.'),('gases','Filtration does not remove dissolved gases.')],'Filter paper holds the solids.'),
  tf('s9-a3',1,'Evaporation can separate salt from water.',True,'Water vapour leaves; salt stays.'),
  mcq('s9-a4',1,'Iron filings can be removed from sand using','a magnet',[('a sieve only','Iron filings may pass.'),('water','Both sink.')],'Iron is magnetic.'),
  mcq('s9-a5',2,'Decantation means','pouring off clear liquid after settling',[('heating a liquid','That is evaporation.'),('shaking a liquid','No.')],'The solid stays at the bottom.'),
  mcq('s9-a6',2,'Sieving works when particles differ in','size',[('colour','Sieves cannot judge colour.'),('smell','Smell is unrelated.')],'Small pass through.'),
  mcq('s9-a7',2,'To separate sand and salt we first','add water',[('use a magnet','Neither is magnetic.'),('handpick','They are too small.')],'Salt dissolves, sand does not.'),
  tf('s9-a8',2,'Churning separates butter from curd.',True,'Spinning separates fat.'),
  mcq('s9-a9',3,'Salt from seawater is obtained by','evaporation',[('sieving','Salt is dissolved.'),('winnowing','That is for grain.')],'Sun evaporates the water.'),
  mcq('s9-a10',3,'Tea leaves are separated from tea by','filtering with a strainer',[('winnowing','That is for dry grain.'),('evaporation','That would remove the liquid.')],'A strainer is a filter.')],
 keep=['mixture','filtration','evaporation'])
